changeSet.sql:
ALTER TABLE player_reports
    ADD CONSTRAINT fk_player_reports_reporter
    FOREIGN KEY (reporter_player_id) REFERENCES player_profiles(id) ON DELETE SET NULL;

ALTER TABLE player_reports
    ADD CONSTRAINT fk_player_reports_reported
    FOREIGN KEY (reported_player_id) REFERENCES player_profiles(id) ON DELETE CASCADE;

ALTER TABLE player_reports
    ADD CONSTRAINT ck_player_reports_status
    CHECK (status IN ('pending', 'reviewed', 'actioned', 'dismissed'));

ALTER TABLE player_reports
    ADD CONSTRAINT ck_player_reports_reason
    CHECK (reason IN (
        'harassment', 'cheating', 'fake_scores', 'no_show',
        'inappropriate_content', 'impersonation', 'spam', 'other'
    ));

-- You cannot report yourself. Cheap here, and the alternative is
-- every caller remembering to check.
ALTER TABLE player_reports
    ADD CONSTRAINT ck_player_reports_not_self
    CHECK (reporter_player_id IS NULL OR reporter_player_id <> reported_player_id);

changeSet.rollback:
ALTER TABLE player_reports DROP CONSTRAINT ck_player_reports_not_self;
ALTER TABLE player_reports DROP CONSTRAINT ck_player_reports_reason;
ALTER TABLE player_reports DROP CONSTRAINT ck_player_reports_status;
ALTER TABLE player_reports DROP CONSTRAINT fk_player_reports_reported;
ALTER TABLE player_reports DROP CONSTRAINT fk_player_reports_reporter;

changeSet.sql:
CREATE UNIQUE INDEX uq_player_reports_open_pair
    ON player_reports (reporter_player_id, reported_player_id)
    WHERE status = 'pending';

ALTER TABLE player_reports ENABLE ROW LEVEL SECURITY;
-- A reporter can file a report as themselves and read back only -- their own. There is deliberately NO policy letting the reported -- player read rows about themselves: the row names the reporter, -- and the whole point is that they never learn who it was. -- -- The SuperAdmin queue does not rely on a policy either. It goes -- through the service-role client from an endpoint that has already -- checked platform_config.super_admin_id, which is how every other -- admin surface in this codebase works. CREATE POLICY player_reports_insert_own ON player_reports FOR INSERT WITH CHECK ( reporter_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid()) );
CREATE POLICY player_reports_select_own ON player_reports FOR SELECT USING ( reporter_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid()) );

changeSet.rollback:
DROP POLICY IF EXISTS player_reports_select_own ON player_reports;
DROP POLICY IF EXISTS player_reports_insert_own ON player_reports;
ALTER TABLE player_reports DISABLE ROW LEVEL SECURITY;
